"""Single-figure view of directly trained forecasts and measured checkpoints."""
HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compute Forecast · Direct model</title><style>
:root{--paper:#f5f1e8;--ink:#23313c;--muted:#606d76;--line:#d9d5cd;--blue:#2658b8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1380px;margin:auto;padding:32px 5vw 60px}header{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:20px}.brand{font-size:11px;letter-spacing:.13em;font-weight:700}a{color:var(--blue)}h1{font:42px/1.15 Georgia,serif;font-weight:400;letter-spacing:-1px;margin:40px 0 12px}.intro{max-width:780px;color:var(--muted);font-size:17px}.status{padding:12px 16px;border-left:2px solid var(--blue);font-size:13px;margin:24px 0}.toolbar{display:flex;flex-wrap:wrap;gap:14px;margin:26px 0 20px;align-items:end}label{display:flex;flex-direction:column;font-size:12px;color:var(--muted);gap:6px}button,select{font:inherit;border:1px solid var(--line);color:var(--ink);background:#fbf9f3;border-radius:4px;padding:10px 12px;min-height:42px;max-width:85vw}button{cursor:pointer}button[aria-pressed=true]{background:var(--ink);color:white}button:focus-visible,select:focus-visible{outline:3px solid #80a4e7;outline-offset:3px}.modes{margin-left:auto;display:flex;gap:7px}.figure{border-block:1px solid var(--line);padding:20px 0}h2{font:24px Georgia,serif;margin:0 0 5px}.small{font-size:12px;color:var(--muted)}svg{display:block;width:100%;height:auto;min-height:280px}svg text{font:12px system-ui,sans-serif;fill:var(--muted)}svg circle{cursor:pointer}svg circle:focus{outline:none;stroke:#b47e32;stroke-width:4}.legend{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;margin:18px 0}.legend i{display:inline-block;width:22px;border-top:2px solid;margin-right:7px;vertical-align:middle}.note{font:19px/1.45 Georgia,serif;color:var(--blue)}#point{min-height:42px;font:12px/1.6 ui-monospace,monospace;color:var(--muted);overflow-wrap:anywhere}.metrics{display:flex;gap:40px;flex-wrap:wrap;margin:25px 0}.metrics strong{display:block;font:26px ui-monospace,monospace}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid var(--line);padding:12px 8px;text-align:right;font-variant-numeric:tabular-nums}th:first-child,td:first-child{text-align:left}details{margin:24px 0;border-top:1px solid var(--line);padding-top:16px}summary{cursor:pointer}details p{max-width:900px;color:var(--muted)}@media(max-width:700px){main{padding:22px 18px}h1{font-size:32px}.modes{margin-left:0}select{max-width:85vw}table{min-width:500px}svg text{font-size:14px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style><main><header><div class="brand">COMPUTE FORECAST / DIRECT MODEL</div><a href="https://howdymary--compute-forecast-observatory-web.us-east.modal.run">Pricing observatory ↗</a></header><h1>A model that forecasts the price.</h1><p class="intro">We fine-tune model weights on observed future price changes. Inspect the sampled forecasts, then see which saved checkpoints earned selection.</p><div id="status" class="status" role="status" aria-live="polite">Loading retained research artifacts…</div>
<div class="toolbar"><label>Training seed<select id="seed"></select></label><label>Historical case<select id="case"></select></label><div class="modes"><button id="price" aria-pressed="true">Price forecast</button><button id="learning" aria-pressed="false">Learning</button><button id="refresh" aria-label="Refresh research results">↻ Refresh</button></div></div>
<section class="figure"><h2 id="title">Historical prices and the selected forecast</h2><div id="subtitle" class="small"></div><div class="legend" id="legend"><span><i style="color:#23313c"></i>Observed</span><span><i style="color:#737c85"></i>Untuned model</span><span><i style="color:#2658b8"></i>Selected checkpoint · q10–q90</span></div><svg id="chart" viewBox="0 0 1160 550" role="img" aria-labelledby="title description"><desc id="description">Source-bound forecast comparisons appear when results are published.</desc></svg><p id="note" class="note">Waiting for measured results.</p><div id="point" aria-live="polite">Select a point to inspect its exact value and source.</div></section><div id="metrics" class="metrics"></div><div class="table-wrap"><table><caption style="text-align:left">Same retrospective cohort · seven-day pinball loss</caption><thead><tr><th>Method</th><th>Loss ↓</th><th>Coverage</th><th>Mean width</th><th>Cells</th></tr></thead><tbody id="table"></tbody></table></div>
<details><summary>What these charts establish</summary><p>The price chart uses matching historical observations, actual model-sampled forecasts and archived outcomes. Empirical q10–q90 bands require separate calibration checks. Connections between horizons 1, 3 and 7 are visual guides.</p><p>The learning chart shows seven-day development pinball at actual saved checkpoints. Lines between checkpoints are visual guides. Selection includes the untuned model at update zero. Regressions and flat forecasts remain visible.</p><p>These periods were previously accessible to the project. Results are additional retrospective analyses. Prospective accuracy, an RL benefit, and a supplementary-signal benefit are not established.</p></details><details><summary>Sources and reproduction</summary><p id="provenance"></p><p><a href="https://github.com/howdymary/mochi-demo/blob/compute-observatory/docs/direct-forecast-v12.md">Methods</a> · <a href="https://github.com/howdymary/mochi-demo/blob/compute-observatory/results/direct-v12/README.md">Artifacts and checksums</a> · <a href="https://github.com/howdymary/mochi-demo/actions/runs/43952200479">Training execution</a></p></details></main><script>
const $=s=>document.querySelector(s),NS='http://www.w3.org/2000/svg',colors=['#2658b8','#39735b','#b47e32'];let data,mode='price',selectedSeed='17',selectedCase='';
const fmt=(x,n=5)=>Number.isFinite(x)?x.toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}):'—';
function el(t,a={},text){const e=document.createElementNS(NS,t);Object.entries(a).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e}
function options(e,rows,value){e.replaceChildren(...rows.map(([v,t])=>{const o=document.createElement('option');o.value=v;o.textContent=t;return o}));if(rows.some(([v])=>String(v)===String(value)))e.value=value}
function point(s,x,y,color,label,r=4){const c=el('circle',{cx:x,cy:y,r,fill:color,tabindex:0,role:'button','aria-label':label});const inspect=()=>$('#point').textContent=label;['pointerenter','click','focus'].forEach(k=>c.addEventListener(k,inspect));c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect()}if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const all=[...s.querySelectorAll('circle[tabindex]')],i=all.indexOf(c);all[(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length].focus()}});s.append(c)}
function frame(xs,ys,label){const s=$('#chart');s.replaceChildren(el('desc',{},label));const xmin=Math.min(...xs),xmax=Math.max(...xs),lo=Math.min(...ys),hi=Math.max(...ys),pad=Math.max((hi-lo)*.12,hi*.015,.001),ymin=Math.max(0,lo-pad),ymax=hi+pad;const x=v=>78+(v-xmin)/Math.max(1,xmax-xmin)*1024,y=v=>465-(v-ymin)/Math.max(.000001,ymax-ymin)*400;for(let i=0;i<=5;i++){const v=ymin+(ymax-ymin)*i/5;s.append(el('line',{x1:78,y1:y(v),x2:1102,y2:y(v),stroke:'#d9d5cd','stroke-dasharray':'2 5'}),el('text',{x:65,y:y(v)+4,'text-anchor':'end'},fmt(v,v<1?4:3)))}s.append(el('text',{x:78,y:25},label));return {s,x,y}}
function line(rows,x,y,kx,ky){return rows.map((r,i)=>(i?'L':'M')+x(r[kx])+','+y(r[ky])).join(' ')}
function drawPrice(){const cases=data.cases.filter(c=>c.seed===Number(selectedSeed));options($('#case'),cases.map(c=>[c.id,c.metadata.gpu_model+' · '+c.metadata.source_id+' · '+c.origin]),selectedCase);selectedCase=$('#case').value;const c=cases.find(c=>c.id===selectedCase);if(!c)return;const origin=Date.parse(c.origin),history=c.history.filter(r=>Date.parse(r.date)>=origin-20*86400000).map(r=>({...r,t:Date.parse(r.date)})),base=c.base.map(r=>({...r,t:Date.parse(r.target_date)})),trained=c.trained.map(r=>({...r,t:Date.parse(r.target_date)}));const {s,x,y}=frame([...history.map(r=>r.t),...trained.map(r=>r.t)],[...history.map(r=>r.value),...base.flatMap(r=>[r.q10,r.q90,r.outcome]),...trained.flatMap(r=>[r.q10,r.q90])],'USD per GPU-hour');let d='';history.forEach((r,i)=>d+=(i&&r.t-history[i-1].t<=86400000?' L':' M')+x(r.t)+','+y(r.value));s.append(el('path',{d,fill:'none',stroke:'#23313c','stroke-width':1.8}),el('line',{x1:x(origin),y1:40,x2:x(origin),y2:465,stroke:'#aaa79e','stroke-dasharray':'4 5'}),el('text',{x:x(origin)-8,y:45,'text-anchor':'end'},'Forecast origin'));
for(const [rows,color]of[[base,'#737c85'],[trained,'#2658b8']]){const polygon=rows.map(r=>x(r.t)+','+y(r.q90)).concat([...rows].reverse().map(r=>x(r.t)+','+y(r.q10))).join(' ');s.append(el('polygon',{points:polygon,fill:color,opacity:.12}),el('path',{d:line(rows,x,y,'t','q50'),fill:'none',stroke:color,'stroke-width':color==='#2658b8'?2.5:1.5,'stroke-dasharray':'5 4'}));for(const r of rows)point(s,x(r.t),y(r.q50),color,r.target_date+' · '+(color==='#2658b8'?'Selected':'Untuned')+' q10/q50/q90: '+[r.q10,r.q50,r.q90].map(v=>fmt(v,7)).join(' / ')+' USD/GPU-hour · '+c.series_id+' · '+c.artifact)}
history.forEach(r=>point(s,x(r.t),y(r.value),'#23313c',r.date+' · observed '+fmt(r.value,7)+' USD/GPU-hour · '+c.series_id+' · history SHA256 '+c.history_sha256,2.4));trained.forEach(r=>point(s,x(r.t),y(r.outcome),'#23313c',r.target_date+' · archived outcome '+fmt(r.outcome,7)+' USD/GPU-hour · '+c.series_id,4.5));[history[0]?.t,origin,...trained.map(r=>r.t)].filter(Number.isFinite).forEach((t,i)=>s.append(el('text',{x:x(t),y:495+(i%2)*18,'text-anchor':'middle'},new Date(t).toISOString().slice(5,10))));$('#title').textContent='Historical prices and the selected forecast';$('#subtitle').textContent=c.metadata.gpu_model+' · '+c.metadata.instrument_class.replaceAll('_',' ')+' · '+c.metadata.source_id+' · seed '+c.seed+' · update '+c.checkpoint_update;const a=base.reduce((v,r)=>v+r.loss,0)/3,b=trained.reduce((v,r)=>v+r.loss,0)/3;$('#note').textContent=(b<a?'Lower':b>a?'Higher':'Unchanged')+' quantile loss in this retrospective case. The full matched cohort is summarized below.'}
function drawLearning(){const rows=data.runs.flatMap(r=>r.checkpoints.map(c=>({...c,seed:r.seed,score:c.development.primary_pinball})));if(!rows.length)return;const {s,x,y}=frame([0,...rows.map(r=>r.update)],rows.map(r=>r.score),'Development seven-day pinball · lower is better');data.runs.forEach((run,i)=>{const rr=rows.filter(r=>r.seed===run.seed).sort((a,b)=>a.update-b.update);s.append(el('path',{d:line(rr,x,y,'update','score'),stroke:colors[i],fill:'none','stroke-width':2}));rr.forEach(r=>point(s,x(r.update),y(r.score),colors[i],'Seed '+r.seed+' · optimizer update '+r.update+' · development pinball '+fmt(r.score,8),run.selected.update===r.update?6:4));s.append(el('text',{x:100,y:45+i*20,style:'fill:'+colors[i]},'Seed '+run.seed+' · selected update '+run.selected.update))});[...new Set(rows.map(r=>r.update))].sort((a,b)=>a-b).forEach(v=>s.append(el('text',{x:x(v),y:505,'text-anchor':'middle'},String(v))));s.append(el('text',{x:590,y:535,'text-anchor':'middle'},'Actual optimizer updates'));$('#title').textContent='Which checkpoints were worth keeping?';$('#subtitle').textContent='Measured saved checkpoints · selection uses development only';$('#note').textContent='Each marker is a saved checkpoint. Lines are guides; regressions remain visible.'}
function render(){if(!data)return;$('#price').setAttribute('aria-pressed',mode==='price');$('#learning').setAttribute('aria-pressed',mode==='learning');$('#legend').hidden=mode!=='price';$('#case').disabled=mode!=='price';if(!data.runs.length){$('#chart').replaceChildren(el('text',{x:78,y:220},'No completed checkpoint evaluation has been published yet.'));$('#note').textContent='Training submitted. No accuracy gain is claimed.';return}options($('#seed'),data.runs.map(r=>[String(r.seed),String(r.seed)]),selectedSeed);selectedSeed=$('#seed').value;if(mode==='price')drawPrice();else drawLearning();const r=data.runs.find(r=>r.seed===Number(selectedSeed));$('#metrics').replaceChildren();[['Optimizer updates',r.optimizer_updates],['Selected update',r.selected.update],['Retrospective origins',r.retrospective.n_origins]].forEach(([label,value])=>{const e=document.createElement('div'),strong=document.createElement('strong'),small=document.createElement('span');strong.textContent=value;small.className='small';small.textContent=label;e.append(strong,small);$('#metrics').append(e)});$('#table').replaceChildren();[['Untuned direct model',r.base],['Selected direct model',r.retrospective],...Object.entries(r.references).map(([k,v])=>[k,v.summary])].forEach(([name,v])=>{const h=v.by_horizon['7'],tr=document.createElement('tr');[name,fmt(v.primary_pinball,8),fmt(h.coverage*100,1)+'%',fmt(h.width,6),h.n_cells].forEach(text=>{const td=document.createElement('td');td.textContent=text;tr.append(td)});$('#table').append(tr)});$('#provenance').textContent=data.source_attribution+' Protocol SHA256 '+data.protocol_sha256+'. '+data.audit.phase_tasks.training+' training windows across '+data.audit.distinct_training_origins+' overlapping origins. Exact source identities, cohorts and denominators remain in the audit.'}
async function load(){const focus=document.activeElement?.id;$('#status').textContent='Loading retained research artifacts…';try{const response=await fetch('/api/direct-v12',{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);data=await response.json();$('#status').textContent=(data.status==='completed'?'Training complete':data.status==='partial'?'Partial results published':'Training submitted')+' · '+data.runs.length+'/3 seeds published. Prospective improvement is not established.';render();if(focus&&$('#'+focus))$('#'+focus).focus()}catch(e){$('#status').textContent='Research artifacts are unavailable. Use Refresh to retry. '+e.message}}
$('#seed').onchange=()=>{selectedSeed=$('#seed').value;render()};$('#case').onchange=()=>{selectedCase=$('#case').value;render()};$('#price').onclick=()=>{mode='price';render()};$('#learning').onclick=()=>{mode='learning';render()};$('#refresh').onclick=load;load();
</script></html>'''
